import numpy as np, pandas as pd, os
import matplotlib.pyplot as plt

ACC={'YjjW_ECOLI':'P39409','BssD_THAAR':'O87941','PflA_ECOLI':'P0A9N4','NrdG_ECOLI':'P0A9N8'}
def sgs(acc):
    sg={}; pl={}
    for L in open(f"AF-{acc}.pdb"):
        if L.startswith("ATOM") and L[17:20].strip()=="CYS" and L[12:16].strip()=="SG":
            sg[int(L[22:26])]=np.array([float(L[30:38]),float(L[38:46]),float(L[46:54])])
            pl[int(L[22:26])]=float(L[60:66])
    return sg,pl
def cluster(sg,cut):
    ks=sorted(sg); par={k:k for k in ks}
    def f(x):
        while par[x]!=x: par[x]=par[par[x]]; x=par[x]
        return x
    for i in range(len(ks)):
        for j in range(i+1,len(ks)):
            if np.linalg.norm(sg[ks[i]]-sg[ks[j]])<=cut:
                a,b=f(ks[i]),f(ks[j])
                if a!=b: par[a]=b
    g={}
    for k in ks: g.setdefault(f(k),[]).append(k)
    return [sorted(v) for v in g.values() if len(v)>=3]

rows=[]
for n,acc in ACC.items():
    sg,pl=sgs(acc)
    for cut in (7.0,):
        for s in cluster(sg,cut):
            d=[np.linalg.norm(sg[a]-sg[b]) for i,a in enumerate(s) for b in s[i+1:]]
            cen=np.mean([sg[x] for x in s],axis=0)
            rows.append(dict(protein=n,acc=acc,cut=cut,site="+".join(f"C{x}" for x in s),
                             n_Cys=len(s),max_SG_SG=round(max(d),2),
                             mean_pLDDT=round(float(np.mean([pl[x] for x in s])),1),
                             cx=cen[0],cy=cen[1],cz=cen[2]))
S=pd.DataFrame(rows)
S.to_csv("activase_FeS_sites.csv",index=False)
print("Candidate [4Fe-4S] sites, single-linkage cut 7.0 A on SG atoms:")
print(S[['protein','site','n_Cys','max_SG_SG','mean_pLDDT']].to_string(index=False))
print("\nSites per protein:"); print(S.groupby('protein').size().to_string())

print("\nCentre-to-centre distances between sites (electron relay geometry):")
for n in S.protein.unique():
    d=S[S.protein==n]
    if len(d)<2: print(f"  {n:12s} single site"); continue
    C=d[['cx','cy','cz']].values; lab=list(d['site'])
    for i in range(len(C)):
        for j in range(i+1,len(C)):
            print(f"  {n:12s} {lab[i]:28s} to {lab[j]:28s} {np.linalg.norm(C[i]-C[j]):6.1f} A")

cnt=S.groupby('protein').size().reindex(['YjjW_ECOLI','BssD_THAAR','PflA_ECOLI','NrdG_ECOLI'])
fig,ax=plt.subplots(figsize=(7.5,4.2))
cols=['#c53030','#2b6cb0','#718096','#718096']
ax.bar([x.split('_')[0] for x in cnt.index], cnt.values, color=cols)
for i,v in enumerate(cnt.values): ax.text(i,v+0.05,str(v),ha='center',fontsize=11)
ax.set_ylabel('Candidate [4Fe-4S] sites in the AlphaFold v6 model')
ax.set_title('YjjW has the three-cluster architecture of BssD, not the single cluster of PflA and NrdG\n'
             'sites defined as 3 or more Cys SG atoms within 7 A, single linkage')
ax.set_ylim(0,3.6); ax.grid(alpha=.3,axis='y')
plt.tight_layout(); plt.show()
